    44	int
    45	count_open_fds()
    46	{
    47	        int i;
    48	        int count = 0;
    49	
    50	        for (i = 0; i < FD_SETSIZE; i++) {
    51	                int fd = dup(i);
    52	
    53	                if (fd >= 0) {
    54	                        count++;
    55	                        if (close(fd) < 0) {
    56	                                perror("count_open_fds");
    57	                                fuzz_trap();
    58	                        }
    59	                }
    60	        }
    61	
    62	        return count;
    63	}
