    68	        FILE *file = tmpfile();
    69	
    70	        fwrite(data, 1, size, file);
    71	        fflush(file);
    72	        rewind(file);
    73	        fread_config(file, &add_to_map, &settings);
    74	        fclose(file);
    75	
    76	        if (!settings.empty()) {
    77	                std::map<std::string, std::string>::const_iterator iter;
    78	
    79	                for(iter = settings.begin(); iter != settings.end(); iter++) {
    80	                        set_config_param(NULL, iter->first.c_str(), iter->second.c_str());
    81	                }
    82	
    83	                try {
    84	                        MainLoop main_loop(settings);
    85	                } catch (nl::SocketError x) {
    86	                        // Ignore socket errors
    87	                } catch (std::invalid_argument x) {
    88	                        // Ignore invalid argument errors
    89	                }
    90	        }
    91	
    92	        return 0;
