    98	int
    99	NCPInputFuzzTarget(const uint8_t *data, size_t size) {
   100	        std::map<std::string, std::string> settings;
   101	
   102	        int fd[2] = { -1, -1 };
   103	        uint8_t data_out[100];
   104	        uint32_t i = 0;
   105	        const uint32_t max_iterations = 10000000;
   106	        static const uint8_t hdlc_flag = HDLC_BYTE_FLAG;
   107	
   108	        gRet = 0;
   109	
   110	        if (socketpair(PF_UNIX, SOCK_STREAM, 0, fd) < 0) {
   111	                syslog(LOG_ALERT, "Call to socketpair() failed: %s (%d)", strerror(errno), errno);
   112	                fuzz_trap();
   113	        }
   114	
   115	        {
   116	                char *fd_string = NULL;
   117	
   118	                if (0 >= asprintf(&fd_string, "fd:%d", fd[1])) {
   119	                        syslog(LOG_ALERT, "Call to asprintf() failed: %s (%d)", strerror(errno), errno);
   120	                        fuzz_trap();
   121	                }
   122	
   123	                assert(fd_string != NULL);
   124	
   125	                settings[kWPANTUNDProperty_ConfigNCPSocketPath] = fd_string;
   126	
   127	                free(fd_string);
   128	        }
   129	
   130	        try {
   131	
   132	        MainLoop main_loop(settings);
   133	
   134	        // wpantund dup'd the file descriptor we gave it,
   135	        // so we should close this one here.
   136	        close(fd[1]);
   137	        fd[1] = -1;
   138	
   139	        for (i = 0; (i < 10) && main_loop.block_until_ready(); i++) {
   140	                main_loop.process();
   141	        }
   142	        main_loop.process();
   143	
   144	        while (size > 0 && gRet == 0) {
   145	                uint8_t c = *data++;
   146	                size--;
   147	
   148	                // Special command.
   149	                if ((size > 0) && (c == HDLC_BYTE_SPECIAL)) {
   150	                        c = *data++;
   151	                        size--;
   152	
   153	                        if (c == FUZZ_SPECIAL_WAIT_FOR_FRAME) {
   154	                                for (i = 0; i < 5 && checkpoll(fd[0], POLLIN|POLLERR|POLLHUP) == 0; i++) {
   155	                                        if (main_loop.block_until_ready()) {
   156	                                                main_loop.process();
   157	                                        } else {
   158	                                                break;
   159	                                        }
   160	                                }
   161	
   162	                                while (checkpoll(fd[0], POLLIN|POLLERR|POLLHUP) != 0 && gRet == 0) {
   163	                                        ssize_t bytesread = read(fd[0], data_out, sizeof(data_out));
   164	                                        if (bytesread <= 0) {
   165	                                                syslog(LOG_WARNING, "Call to read() failed: %s (%d)", strerror(errno), errno);
   166	                                                goto bail;
   167	                                        }
   168	
   169	                                        if (main_loop.block_until_ready()) {
   170	                                                main_loop.process();
   171	                                        } else {
   172	                                                break;
   173	                                        }
   174	#if DEBUG
   175	                                        fprintf(stderr, "NCPInputFuzzTarget: Got %lu bytes from wpantund\n", bytesread);
   176	#endif
   177	                                }
   178	                                continue;
   179	                        } else if ((c == FUZZ_SPECIAL_FF_DECISECONDS) && (size > 0)) {
   180	                                c = *data++;
   181	                                size--;
   182	                                // Fast forward the given number of deciseconds
   183	                                fuzz_ff_cms(c * (MSEC_PER_SEC/10));
   184	                        }
   185	                }
   186	
   187	                while (checkpoll(fd[0], POLLOUT|POLLERR|POLLHUP) == 0 && gRet == 0) {
   188	                        main_loop.block_until_ready();
   189	                        main_loop.process();
   190	                }
   191	
   192	                ssize_t byteswritten = write(fd[0], &c, 1);
   193	                if (byteswritten <= 0) {
   194	                        syslog(LOG_WARNING, "Call to write() failed: %s (%d)", strerror(errno), errno);
   195	                        goto bail;;
   196	                }
   197	
   198	                main_loop.block_until_ready();
   199	                main_loop.process();
   200	        }
   201	
   202	        for (i = 0; (i < 10) && main_loop.block_until_ready(); i++) {
   203	                main_loop.process();
   204	        }
   205	        main_loop.process();
   206	
   207	        if (size != 0) {
   208	                syslog(LOG_ALERT, "Did not consume all data");
   209	                fuzz_trap();
   210	        }
   211	
   212	        if (gRet != 0) {
   213	                syslog(LOG_ALERT, "gRet = %d", gRet);
   214	                fuzz_trap();
   215	        }
   216	
   217	        } catch (nl::SocketError x) {
   218	                // Ignore socket wrapper errors
   219	        }
   220	
   221	bail:
   222	        close(fd[0]);
   223	        close(fd[1]);
   224	
   225	        return 0;
   226	}
