   236	LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
   237	        int ret = 0;
   238	        static bool did_init;
   239	
   240	        if (!did_init) {
   241	                did_init = true;
   242	
   243	                openlog("wpantund-fuzz", LOG_PERROR|LOG_NDELAY, LOG_USER);
   244	
   245	#if DEBUG
   246	                setlogmask(LOG_UPTO(LOG_INFO));
   247	#else
   248	                setlogmask(LOG_UPTO(LOG_ALERT));
   249	#endif
   250	
   251	                signal(SIGPIPE, SIG_IGN);
   252	        }
   253	
   254	        fuzz_set_cms(0);
   255	
   256	        int fd_count_before = -1;
   257	        int fd_count_after = -1;
   258	
   259	        // Count the number of FDs before starting fuzzing.
   260	        fd_count_before = count_open_fds();
   261	        if (fd_count_before > 1000) {
   262	                syslog(LOG_ALERT, "Too many file descriptors open: %d (max %d)", fd_count_before, 1000);
   263	                fuzz_trap();
   264	        }
   265	
   266	        if (size >= 1) {
   267	                char type = *data++;
   268	                size--;
   269	                switch (type) {
   270	                case '0': // Config file fuzzing
   271	                        ret = ConfigFileFuzzTarget(data, size);
   272	                        break;
   273	
   274	                case '1': // NCP Input fuzzing
   275	                        ret = NCPInputFuzzTarget(data, size);
   276	                        break;
   277	
   278	                case '2': // NCPControlInterface fuzzing
   279	                        ret = NCPControlInterfaceFuzzTarget(data, size);
   280	                        break;
   281	
   282	                default:
   283	                        break;
   284	                }
   285	        }
   286	
   287	        // Count the number of FDs after finishing fuzzing.
   288	        fd_count_after = count_open_fds();
   289	        if (fd_count_before != fd_count_after) {
   290	                syslog(LOG_ALERT, "File descriptor count changed durring run! before=%d after=%d", fd_count_before, fd_count_after);
   291	                fuzz_trap();
   292	        }
   293	
   294	        return ret;
   295	}
